import {describe, test, expect} from 'vitest';
import {parse} from '../../src/main.js';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {readFile} from 'node:fs/promises';

const fixtureDir = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  '../fixtures'
);

describe('yarn parser', () => {
  test('parse simple yarn lock file', async () => {
    const input = `
# This file is generated by running "yarn install" inside your project.
# Manual changes might be lost - proceed with caution!

__metadata:
  version: 8
  cacheKey: 10

"some-package@npm:^1.0.0":
  version: 1.2.3
  resolution: some-package@npm:1.2.3
  dependencies:
    another-package: npm:^2.0.0

"another-package@npm:^2.0.0":
  version: 2.3.4
  resolution: another-package@npm:2.3.4
`;
    const parsed = await parse(input, 'yarn');
    expect(parsed).toMatchSnapshot();
  });

  test('populates root from package.json', async () => {
    const input = `
"some-package@npm:^1.0.0":
  version: 1.2.3
  resolution: some-package@npm:1.2.3
  dependencies:
    another-package: npm:^2.0.0

"another-package@npm:^2.0.0":
  version: 2.3.4
  resolution: another-package@npm:2.3.4
`;
    const packageJson = {
      name: 'my-project',
      version: '1.0.0',
      dependencies: {
        'some-package': '^1.0.0'
      }
    };
    const parsed = await parse(input, 'yarn', packageJson);
    expect(parsed).toMatchSnapshot();
  });

  test('parses a complex yarn lock file', async () => {
    const input = await readFile(path.join(fixtureDir, 'yarn.lock'), 'utf-8');
    const parsed = await parse(input, 'yarn');
    expect(parsed).toMatchSnapshot();
  });

  test('parses a complex yarn v1 lock file', async () => {
    const input = await readFile(
      path.join(fixtureDir, 'yarn-v1.lock'),
      'utf-8'
    );
    const parsed = await parse(input, 'yarn');
    expect(parsed).toMatchSnapshot();
  });

  test('handles optional dependencies', async () => {
    const input = `
"some-package@npm:^1.0.0":
  version: 1.2.3
  resolution: some-package@npm:1.2.3
  dependencies:
    another-package: npm:^2.0.0
  dependenciesMeta:
    another-package:
      optional: true

"another-package@npm:^2.0.0":
  version: 2.3.4
  resolution: another-package@npm:2.3.4
`;
    const parsed = await parse(input, 'yarn');
    expect(parsed).toMatchSnapshot();
  });

  test('handles optional dependencies seen before dependency', async () => {
    const input = `
"some-package@npm:^1.0.0":
  version: 1.2.3
  resolution: some-package@npm:1.2.3
  dependenciesMeta:
    another-package:
      optional: true
  dependencies:
    another-package: npm:^2.0.0

"another-package@npm:^2.0.0":
  version: 2.3.4
  resolution: another-package@npm:2.3.4
`;
    const parsed = await parse(input, 'yarn');
    expect(parsed).toMatchSnapshot();
  });

  test('resolves aliased dependencies', async () => {
    const input = await readFile(
      path.join(fixtureDir, 'yarn-alias.lock'),
      'utf-8'
    );
    const packageJson = {
      dependencies: {foo: 'npm:tinyexec@1.4.0', bar: 'npm:tinyglobby@0.2.17'}
    };
    const parsed = await parse(input, 'yarn', packageJson);
    const rootDeps = parsed.root.dependencies.map(
      (d) => `${d.name}@${d.version}`
    );
    expect(rootDeps).toEqual(['tinyexec@1.4.0', 'tinyglobby@0.2.17']);
    const tinyglobby = parsed.root.dependencies.find(
      (d) => d.name === 'tinyglobby'
    )!;
    expect(tinyglobby.dependencies.map((d) => d.name)).toEqual([
      'fdir',
      'picomatch'
    ]);
  });

  test('resolves aliased dependencies in yarn v1', async () => {
    const input = await readFile(
      path.join(fixtureDir, 'yarn-v1-alias.lock'),
      'utf-8'
    );
    const packageJson = {
      dependencies: {foo: 'npm:tinyexec@1.4.0', bar: 'npm:tinyglobby@0.2.17'}
    };
    const parsed = await parse(input, 'yarn', packageJson);
    const rootDeps = parsed.root.dependencies.map(
      (d) => `${d.name}@${d.version}`
    );
    expect(rootDeps).toEqual(['tinyexec@1.4.0', 'tinyglobby@0.2.17']);
    const tinyglobby = parsed.root.dependencies.find(
      (d) => d.name === 'tinyglobby'
    )!;
    expect(tinyglobby.dependencies.map((d) => d.name)).toEqual([
      'fdir',
      'picomatch'
    ]);
  });
});
